import manifest from './portraitManifest.json';
// Responsive WebP portraits generated by scripts/prepare-web-portraits.mjs.
// Falls back to the original PNG when a puppy has no generated portrait.
export function portraitSources(id,fallback){
 const p=manifest[id];
 if(!p)return {src:fallback};
 const srcSet=[['small',256],['large',640],['full',1536]].filter(([k])=>p[k])
  .map(([k,w])=>`${p[k]} ${p[k+'Width']||w}w`).join(', ');
 return {src:p.large||p.small||fallback,srcSet:srcSet||undefined};
}
// A small, usually already-cached thumbnail for placeholders.
export const portraitThumbnail=id=>manifest[id]?.small||null;
